function journeyFingerprint(sessions){const source=JSON.stringify(sessions.map(s=>[s.id,s.date,s.count,s.seconds,s.mode]));let hash=2166136261;for(let i=0;i<source.length;i++){hash^=source.charCodeAt(i);hash=Math.imul(hash,16777619)}return(hash>>>0).toString(16)}
function journeySnapshot(journey=null){const sessions=[...(journey?.sessions||data.sessions)].sort((a,b)=>new Date(a.date)-new Date(b.date));return{sessions,total:sessions.reduce((n,s)=>n+Number(s.count),0),name:journey?.name||data.profile?.name||'',generatedAt:new Date().toISOString(),isArchive:!!journey,fingerprint:journeyFingerprint(sessions)}}
function selectedJourney(){const id=$('#journey-history-select')?.value;return(data.journeys||[]).find(j=>j.id===id)||null}
function canStartNewJourney(){const receipt=data.recognitionReceipt;return total()>=1000000&&!!receipt?.confirmed&&receipt.fingerprint===journeySnapshot().fingerprint&&!running&&!elapsed}
function refreshMilestone(){const key=[total(),data.sessions.length,data.recognitionReceipt?.fingerprint||'',data.recognitionReceipt?.confirmedAt||'',running,elapsed>0].join('|');if(refreshMilestone.last===key)return;refreshMilestone.last=key;const eligible=canStartNewJourney(),done=total()>=1000000;$('#reset-journey').disabled=!eligible;$('#milestone-recognition').classList.toggle('hidden',!done);$('#milestone-copy').textContent=!done?'Al llegar al millón, guarda tu reconocimiento para comenzar otro recorrido.':running||elapsed?'Guarda o descarta la sesión en curso antes de iniciar otro recorrido.':eligible?'Tu reconocimiento está guardado. Puedes abrir un nuevo camino; este quedará archivado.':'¡Completaste el millón! Descarga tu reconocimiento y confirma que lo guardaste para comenzar otro recorrido.'}
function csvForJourney(snapshot){const lines=[['Fecha','Hora','Daimoku','Duración_segundos','Modo','Acumulado']];let cumulative=0;for(const session of snapshot.sessions){cumulative+=session.count;const date=new Date(session.date);lines.push([date.toLocaleDateString('es-CL'),date.toLocaleTimeString('es-CL',{hour12:false}),session.count,Math.round(session.seconds),{listen:'Estimación con voz',timer:'Estimación por tiempo',manual:'Registro manual'}[session.mode]||session.mode,cumulative])}return'\uFEFF'+lines.map(row=>row.map(value=>'"'+String(value).replaceAll('"','""')+'"').join(';')).join('\r\n')}
function downloadFile(content,type,name){const blob=content instanceof Blob?content:new Blob([content],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function reportDate(value,short=false){return new Date(value).toLocaleDateString('es-CL',short?{day:'2-digit',month:'2-digit',year:'numeric'}:{day:'numeric',month:'long',year:'numeric'})}
function reportFormat(value){return Math.floor(value).toLocaleString('es-CL')}
function buildJourneyPDF(snapshot,{recognition=false,name=snapshot.name||''}={}){
 const Pdf=globalThis.jspdf?.jsPDF;if(!Pdf)throw new Error('No se pudo cargar el generador PDF. Recarga la app.');const doc=new Pdf({unit:'mm',format:'a4',compress:true});const ink=[24,52,76],blue=[30,86,140],red=[205,73,64],muted=[90,113,131];let pages=0;
 const txt=(value,x,y,size=11,color=ink,weight='normal',opts={})=>{doc.setFont('helvetica',weight);doc.setFontSize(size);doc.setTextColor(...color);doc.text(Array.isArray(value)?value:String(value),x,y,opts)};
 const paragraph=(value,x,y,width,size=10,color=muted)=>{doc.setFont('helvetica','normal');doc.setFontSize(size);doc.setTextColor(...color);const lines=doc.splitTextToSize(String(value),width);doc.text(lines,x,y,{lineHeightFactor:1.5});return y+lines.length*size*.3528*1.5};
 const rect=(x,y,w,h,color)=>{doc.setFillColor(...color);doc.rect(x,y,w,h,'F')};
 function pageBase(){pages++;rect(0,0,210,297,[250,251,248]);rect(17,17,58,.9,blue);rect(75,17,58,.9,[209,219,225]);rect(133,17,60,.9,red);txt('daimoku chile',18,31,13,ink,'bold');txt('CADA DAIMOKU CUENTA',192,31,7,muted,'normal',{align:'right'});doc.setDrawColor(214,224,229);doc.setLineWidth(.25);doc.line(18,279,192,279);txt('Una práctica personal. Un horizonte compartido.',18,285,7,muted);txt(String(pages),192,285,7,muted,'normal',{align:'right'})}
 function geographicMap(x,y,height){const scale=height/630,ops=[];const outline=CHILE_MAP.path.split('M').filter(Boolean).filter(r=>parseFloat(r.split(',')[0])>=95).map(r=>'M'+r).join(' ');const parts=outline.match(/[MLZ]|-?\d+(?:\.\d+)?/g)||[];let at=0;while(at<parts.length){const type=parts[at++];if(type==='Z')ops.push({op:'h',c:[]});else{const px=Number(parts[at++]),py=Number(parts[at++]);ops.push({op:type==='M'?'m':'l',c:[x+(px-95)*scale,y+(py-20)*scale]})}}doc.setFillColor(228,236,240);doc.path(ops);doc.fill();const completed=Math.min(1000,Math.floor(snapshot.total/1000));CHILE_MAP.cells.slice(0,completed).forEach(([px,py],i)=>{if(px<95)return;const hex=MAP_TILE_COLORS[i],rgb=[1,3,5].map(a=>parseInt(hex.slice(a,a+2),16));rect(x+(px-95)*scale,y+(py-20)*scale,CHILE_MAP.step*scale,CHILE_MAP.step*scale,rgb)});doc.setDrawColor(47,88,118);doc.setLineWidth(.18);doc.path(ops);doc.stroke()}
 const dates=snapshot.sessions.map(s=>new Date(s.date).toLocaleDateString('en-CA'));const days=new Set(dates).size,period=snapshot.sessions.length?`${reportDate(snapshot.sessions[0].date)} al ${reportDate(snapshot.sessions.at(-1).date)}`:'Sin sesiones guardadas';
 if(recognition){pageBase();txt('RECONOCIMIENTO PERSONAL',18,51,9,blue,'bold');txt('Cada daimoku',18,73,32,ink,'bold');txt('cuenta.',18,88,32,red,'bold');txt('Este recorrido pertenece a',18,107,11,muted);doc.setFont('helvetica','bold');doc.setFontSize(24);const identity=doc.splitTextToSize(name.trim()||'Tu propio camino',126).slice(0,2);txt(identity,18,123,24,ink,'bold');paragraph(snapshot.total>=1000000?'Por completar un millón de daimoku y cultivar, paso a paso, un camino de dedicación y constancia.':'Por dar un lugar a tu intención y cultivar, paso a paso, un camino de dedicación y constancia.',18,151,124,11,muted);txt(reportFormat(snapshot.total),18,187,33,blue,'bold');txt('DAIMOKU REGISTRADOS',19,197,9,muted);txt(`${snapshot.sessions.length} sesiones`,18,216,12,ink,'bold');txt(`${days} ${days===1?"día":"días"} con práctica`,76,216,12,ink,'bold');const progress=Math.min(1,snapshot.total/1000000);rect(18,228,124,2,[218,228,233]);if(progress)rect(18,228,124*progress,2,red);txt(`${Math.min(1000,Math.floor(snapshot.total/1000))} de 1.000 cuadros - ${(progress*100).toLocaleString('es-CL',{maximumFractionDigits:2})}% del viaje`,18,239,9,muted);paragraph('Recorrido: '+period,18,251,170,9,muted);txt('Generado el '+reportDate(snapshot.generatedAt),18,267,8,muted);geographicMap(148,59,184);txt('Reconocimiento personal, sin afiliación ni aval de SGI.',18,275,7,muted);doc.addPage()}
 pageBase();txt('Tu bitácora por Chile',18,50,24,ink,'bold');if(name.trim())txt(name.trim().slice(0,65),18,60,11,muted);let y=name.trim()?71:63;y=paragraph(period,18,y,174,9,muted)+9;txt(`${reportFormat(snapshot.total)} daimoku`,18,y,17,blue,'bold');txt(`${snapshot.sessions.length} sesiones · ${days} ${days===1?"día":"días"}`,192,y,10,muted,'normal',{align:'right'});y+=9;txt(`${Math.min(1000,Math.floor(snapshot.total/1000))} cuadros completos de 1.000`,18,y,9,muted);y+=12;
 function tableHead(){rect(18,y-5,174,9,[229,237,241]);txt('FECHA / HORA',21,y+1,8,blue,'bold');txt('DAIMOKU',108,y+1,8,blue,'bold',{align:'right'});txt('MINUTOS',136,y+1,8,blue,'bold',{align:'right'});txt('ACUMULADO',189,y+1,8,blue,'bold',{align:'right'});y+=13}
 tableHead();let accumulated=0;if(!snapshot.sessions.length){txt('Tu primera sesión guardada aparecerá aquí.',21,y+3,10,muted);y+=20}
 for(const session of snapshot.sessions){if(y>251){doc.addPage();pageBase();txt('Tu bitácora - continuación',18,49,18,ink,'bold');y=65;tableHead()}accumulated+=session.count;const time=new Date(session.date).toLocaleTimeString('es-CL',{hour:'2-digit',minute:'2-digit'});txt(reportDate(session.date,true)+' '+time,21,y,8.5,ink);txt(reportFormat(session.count),108,y,10,ink,'bold',{align:'right'});txt((session.seconds/60).toLocaleString('es-CL',{maximumFractionDigits:1}),136,y,9,ink,'normal',{align:'right'});txt(reportFormat(accumulated),189,y,9,ink,'normal',{align:'right'});txt({listen:'Estimación con voz',timer:'Estimación por tiempo',manual:'Registro manual'}[session.mode]||'Registro personal',21,y+4,7,muted);doc.setDrawColor(222,230,235);doc.line(18,y+7,192,y+7);y+=14}
 if(y>238){doc.addPage();pageBase();y=49}paragraph('El conteo por voz y tiempo es estimado. Cada cuadro representa 1.000 daimoku. Este documento refleja las sesiones guardadas al generarlo y no es una certificación oficial.',18,y+8,174,8,muted);doc.setProperties({title:recognition?'Mi reconocimiento y bitácora - Daimoku Chile':'Mi bitácora - Daimoku Chile',subject:'Recorrido personal y sesiones guardadas',author:'Daimoku Chile',creator:'Daimoku Chile - generación local'});return doc;
}
async function saveJourneyPDF(snapshot,recognition=false,name=snapshot.name){const doc=buildJourneyPDF(snapshot,{recognition,name});await doc.save(`${recognition?'reconocimiento':'bitacora'}-daimoku-chile-${localDay(Date.now())}.pdf`,{returnPromise:true});return doc}
function showExportOptions(){const snapshot=journeySnapshot(selectedJourney());modal(`<h2>Tu camino, para conservar.</h2><p>${fmt(snapshot.total)} daimoku en ${snapshot.sessions.length} sesiones${snapshot.isArchive?' de un recorrido archivado':''}. Elige cómo llevarlos contigo.</p><div class="export-choices"><button class="secondary" id="csv-download"><b>Excel y hojas de cálculo</b><small>Archivo CSV con cada sesión y su acumulado.</small></button><button class="secondary" id="pdf-download"><b>Bitácora en PDF</b><small>Un documento legible para guardar o imprimir.</small></button><button class="secondary" id="json-download"><b>Respaldo técnico en JSON</b><small>Datos completos, incluidos los recorridos archivados.</small></button></div>`);$('#csv-download').onclick=()=>{downloadFile(csvForJourney(snapshot),'text/csv;charset=utf-8','bitacora-daimoku-chile.csv');toast('Se solicitó la descarga de tu CSV')};$('#json-download').onclick=()=>downloadFile(JSON.stringify({app:'Daimoku Chile',exportedAt:new Date().toISOString(),...data},null,2),'application/json','respaldo-daimoku-chile.json');$('#pdf-download').onclick=async()=>{try{await saveJourneyPDF(snapshot);toast('Se solicitó la descarga de tu bitácora PDF')}catch(e){toast(e.message)}}}
function showRecognition(journey=selectedJourney()){const snapshot=journeySnapshot(journey);if(!snapshot.sessions.length)return toast('Guarda tu primera sesión para generar un reconocimiento.');modal(`<h2>Cada paso merece un lugar.</h2><p>Tu reconocimiento incluirá ${fmt(snapshot.total)} daimoku, el mapa de tu avance y la bitácora completa. Es personal y no constituye una certificación oficial.</p><label for="recognition-name">Tu nombre o seudónimo (opcional)</label><input id="recognition-name" maxlength="60" value="${esc(snapshot.name)}" placeholder="Como quieres aparecer en tu reconocimiento"><button class="primary" id="recognition-download">Descargar reconocimiento PDF</button><div id="recognition-confirm" class="hidden"><p>Revisa la descarga. Cuando tu PDF esté guardado, confírmalo para habilitar un nuevo recorrido.</p><button class="secondary" id="recognition-saved">Ya guardé mi reconocimiento</button></div>`);$('#recognition-download').onclick=async()=>{const name=$('#recognition-name').value.trim();try{await saveJourneyPDF(snapshot,true,name);if(!journey){data.profile={...(data.profile||{}),name};persist()}if(!journey&&snapshot.total>=1000000&&snapshot.fingerprint===journeySnapshot().fingerprint){$('#recognition-confirm').classList.remove('hidden');$('#recognition-saved').onclick=()=>{if(snapshot.fingerprint!==journeySnapshot().fingerprint)return toast('El recorrido cambió. Genera un reconocimiento actualizado.');data.recognitionReceipt={fingerprint:snapshot.fingerprint,total:snapshot.total,confirmed:true,confirmedAt:new Date().toISOString()};persist();refreshMilestone();$('#modal').close();toast('Reconocimiento confirmado. Tu próximo recorrido está disponible.')}}else toast('Se solicitó la descarga de tu reconocimiento PDF')}catch(e){toast(e.message)}}}
function startNewJourney(){if(!canStartNewJourney())return toast('Completa el millón y guarda su reconocimiento antes de reiniciar.');modal(`<h2>Un nuevo horizonte.</h2><p>Se archivarán tus ${fmt(total())} daimoku y sus sesiones. El nuevo mapa comenzará en cero. Tus intenciones y tu ritmo se conservarán; podrás volver a descargar el reconocimiento anterior desde la bitácora.</p><button class="primary" id="confirm-new-journey">Archivar y comenzar de nuevo</button><button class="text-button" id="cancel-new-journey">Seguir con este recorrido</button>`);$('#cancel-new-journey').onclick=()=>$('#modal').close();$('#confirm-new-journey').onclick=()=>{if(!canStartNewJourney())return toast('El recorrido cambió. Revisa el reconocimiento antes de continuar.');const snapshot=journeySnapshot();const archive={id:crypto.randomUUID(),name:snapshot.name,sessions:data.sessions.map(s=>({...s})),completedAt:new Date().toISOString(),recognitionReceipt:{...data.recognitionReceipt}};const next={...data,sessions:[],journeys:[...(data.journeys||[]),archive],recognitionReceipt:null};try{localStorage.setItem(KEY,JSON.stringify(next))}catch{return toast('No se pudo archivar por falta de espacio. El recorrido no se reinició.')}data=next;$('#journey-history-select').value='';mapCamera.mode='follow';render();$('#modal').close();location.hash='inicio';toast('Nuevo recorrido iniciado. El anterior quedó archivado.')}}
function renderJourneyHistory(){const selector=$('#journey-history-select'),previous=selector.value;selector.innerHTML='<option value="">Mi recorrido actual</option>'+(data.journeys||[]).map((j,i)=>`<option value="${j.id}">Recorrido ${i+1} - ${reportDate(j.completedAt,true)} - ${fmt(j.sessions.reduce((n,s)=>n+s.count,0))} daimoku</option>`).join('');selector.value=(data.journeys||[]).some(j=>j.id===previous)?previous:'';const archive=selectedJourney(),snapshot=journeySnapshot(archive);$('#history-summary').textContent=archive?'Recorrido archivado. Sus registros se conservan completos.':`${snapshot.sessions.length} sesiones guardadas - ${fmt(snapshot.total)} daimoku en este recorrido.`;
 $('#history').innerHTML=snapshot.sessions.length?[...snapshot.sessions].reverse().map(s=>`<article class="record"><div><strong>${reportDate(s.date)}</strong><p>${{listen:'Estimación con voz',timer:'Estimación por tiempo',manual:'Registro manual'}[s.mode]||'Registro'} · ${Math.floor(s.seconds/60)} min ${Math.floor(s.seconds%60)} s</p></div><strong>${fmt(s.count)} daimoku</strong>${archive?'':`<button class="delete" data-session="${s.id}" aria-label="Eliminar sesión">×</button>`}</article>`).join(''):'<div class="empty"><span>▤</span>Tu camino comienza con la primera sesión.<br>Lo que cultives hoy aparecerá aquí.</div>';
 $$('[data-session]').forEach(b=>b.onclick=()=>{modal('<h2>Eliminar esta sesión</h2><p>Esta sesión dejará de sumar al mapa y a tu bitácora.</p><button class="primary" id="confirm-delete">Eliminar sesión</button>');$('#confirm-delete').onclick=()=>{data.sessions=data.sessions.filter(s=>s.id!==b.dataset.session);persist();render();$('#modal').close();toast('Sesión eliminada')}});selector.onchange=renderJourneyHistory;
}
function initJourneyExports(){$('#export').onclick=showExportOptions;$('#recognition').onclick=()=>showRecognition();$('#milestone-recognition').onclick=()=>showRecognition(null);$('#reset-journey').onclick=startNewJourney}
